/* flashcards_m6.js — Módulo 6: Ética e Responsabilidade Digital no Serviço Público
 * 50 flashcards autorais, distribuídos entre as 6 unidades do M6, no MESMO
 * esquema de flashcards_m4.js / flashcards_m5.js / flashcards_m7.js / flashcards_m8.js:
 * id, modulo, topico, nivel, frente, verso, explicacao, revisao, acertos,
 * dificuldade. O campo `topico` referencia o código de tópico do currículo
 * deste módulo (ex.: "m6-u1-t2" corresponde a "modulo-6-unidade-1-topico-2" e
 * aos subtópicos m6-u1-t2-sN).
 *
 * RASTREABILIDADE: os 50 cartões derivam de conteúdo real de
 * curriculum_m6.js (6.1 a 6.6; 18 tópicos; 46 subtópicos), lido na íntegra
 * antes da escrita. Nenhum dispositivo legal citado aqui é inventado: são
 * apenas os que o próprio currículo registra — Lei nº 12.527/2011 (LAI),
 * Lei nº 14.129/2021 (Governo Digital), Constituição Federal (art. 37,
 * caput, e art. 5º, XXXIII) e LGPD (Lei nº 13.709/2018), todos verificados
 * contra o planalto.gov.br em 2026-10-21, com a LGPD verificada em
 * 2026-10-20 (referencias/referencias-verificadas.md).
 *
 * REDUNDÂNCIA: cada cartão testa um conceito distinto. A distribuição
 * acompanha a carga de cobrança indicada pela especificação do projeto:
 * 6.1 = 9 · 6.2 = 13 · 6.3 = 8 · 6.4 = 7 · 6.5 = 5 · 6.6 = 8 (total 50).
 * Quatro cartões da unidade 6.2 (fc-m6-19 a fc-m6-22) são dedicados à
 * distinção entre publicidade administrativa e divulgação irrestrita de
 * dados pessoais, que é o ponto que mais altera o gabarito.
 *
 * AUTORIA: todas as questões e exemplos são AUTORAIS deste projeto.
 * Nenhum cartão reproduz item de banca real nem é atribuído a qualquer banca.
 *
 * INTEGRAÇÃO: a tag <script src="assets/data/flashcards_m6.js"></script> está
 * no index.html (linha 417) desde o P1-C (2026-10-21). O navigation.js e o
 * flashcards.js reconhecem a global flashcardsM6 via typeof, de modo que os 50
 * cartões aparecem na UI sem alteração de lógica. Este cabeçalho antes
 * registrava a tag como pendência — informação superada pelo P1-C.
 */

const flashcardsM6 = [
  // 6.1 Princípios constitucionais aplicados a sistemas e serviços digitais (9 flashcards)
  { id: "fc-m6-01", modulo: 6, topico: "m6-u1-t1", nivel: "basico", frente: "Quais são os cinco princípios da Administração Pública listados no caput do art. 37 da Constituição Federal?", verso: "Legalidade, impessoalidade, moralidade, publicidade e eficiência. A Administração pública direta e indireta de qualquer dos Poderes da União, dos Estados, do Distrito Federal e dos Municípios obedece a todos eles.", explicacao: "O caput do art. 37 é a base constitucional que reúne os cinco em um único dispositivo. O art. 5º, XXXIII, assegura a todos o direito de receber informações de interesse particular, coletivo ou geral, ressalvadas as de sigilo imprescindível à segurança da sociedade e do Estado: publicidade e sigilo convivem por desenho, não por oposição.", revisao: null, acertos: 0, dificuldade: "facil" },
  { id: "fc-m6-02", modulo: 6, topico: "m6-u1-t1", nivel: "intermediario", frente: "Qual a diferença técnica entre princípio e regra, e por que ela altera o gabarito?", verso: "Princípio é norma de conduta de textura aberta, que orienta e limita a atuação e por isso exige ponderação e concretização; regra vincula o agente de forma direta e exaustiva. Exemplo verificado: o prazo de 20 dias para responder a pedido de acesso (art. 11, § 1º, da Lei nº 12.527/2011) é regra — não se pondera, apenas se prorroga nos termos do art. 11, § 2º.", explicacao: "É na área de TI que o princípio vira problema, porque a tecnicização do serviço público é o espaço da concretização: um princípio abstrato só se prova por evidência de configuração, log ou versão de regra. Tratar princípio como se fosse regra, com prazo e valor exatos, é generalização falsa.", revisao: null, acertos: 0, dificuldade: "medio" },
  { id: "fc-m6-03", modulo: 6, topico: "m6-u1-t2", nivel: "intermediario", frente: "O que a automação de um ato administrativo não faz?", verso: "Não cria competência — o sistema não decide sobre o que o órgão não tem competência para decidir; não substitui a motivação — a decisão automatizada continua sendo ato administrativo e precisa de fatos, fundamentos e critério; não afasta publicidade e contraditório; e não neutraliza a responsabilidade: a assinatura eletrônica define AUTOR, não exonera o órgão.", explicacao: "A legalidade em sistema decisório exige base normativa para coletar, tratar e decidir, competência do sistema e dos agentes, previsão de quem responde pelo resultado do algoritmo e integração do sistema ao procedimento formal (protocolo, decisão, notificação, recurso).", revisao: null, acertos: 0, dificuldade: "medio" },
  { id: "fc-m6-04", modulo: 6, topico: "m6-u1-t2", nivel: "intermediario", frente: "Na impessoalidade aplicada ao serviço público digital, quais são as quatro qualidades que o critério de decisão precisa ter?", verso: "Estar definido previamente, escrito, comunicável ao cidadão e auditável. A exigência vale para todos os critérios de ordenação, pontuação, aprovação, exibição e priorização.", explicacao: "Impessoalidade não é indiferença nem ausência de contexto: a lei pode determinar tratamento diferenciado, e o que não pode é o critério ser definido por preferência pessoal, por interesse de cliente ou por identificador de cliente sem ancoragem normativa. O que se veda é o arbítrio, não a diferenciação legal.", revisao: null, acertos: 0, dificuldade: "medio" },
  { id: "fc-m6-05", modulo: 6, topico: "m6-u1-t2", nivel: "avancado", frente: "Um portal exibe a posição do cidadão na fila sem informar os critérios. Quais princípios são afetados e por que corrigir só um deles é insuficiente?", verso: "Impessoalidade e publicidade. Sem critério escrito e comunicável não se demonstra tratamento igualitário (impessoalidade), e o cidadão não sabe como sua posição foi determinada, o que impede controlar a atividade do órgão (publicidade). Critério oculto é, ao mesmo tempo, os dois defeitos.", explicacao: "Corrigir apenas a impessoalidade (escrever o critério), sem publicar (divulgar o critério e a versão vigente), deixa metade do problema. E o mesmo caso mostra por que a impessoalidade material exige mais: aplicar a mesma regra a todos pode, ainda assim, tratar desigualmente quem está em situação análoga, se o dado de entrada reflete desigualdade estrutural — daí a análise por subgrupo.", revisao: null, acertos: 0, dificuldade: "dificil" },
  { id: "fc-m6-06", modulo: 6, topico: "m6-u1-t2", nivel: "intermediario", frente: "Como a moralidade se manifesta no tratamento de dados em sistema público digital?", verso: "Em quatro deveres: compatibilidade entre a finalidade declarada e a finalidade real do tratamento (recolher dado de saúde para «melhorar o atendimento» e usá-lo em ranking é desvio de finalidade); vedação ao uso oportunista de dado de terceiro (deixar o cidadão «aceitar» termos irrelevantes para obter geolocalização); honestidade na comunicação do serviço (não prometer atendimento digital que não existe); e integridade na representação institucional.", explicacao: "Moralidade é retidão, honestidade, ética e boa-fé; opera na zona não coberta por lei e COMPLEMENTA a legalidade, não a substitui — legalidade sem moralidade admitiria prática cruel dentro da letra da lei. O item que a trata como cláusula de fechamento aplicável só quando a lei é silente está errado.", revisao: null, acertos: 0, dificuldade: "medio" },
  { id: "fc-m6-07", modulo: 6, topico: "m6-u1-t3", nivel: "intermediario", frente: "Como se distinguem publicidade, transparência ativa e transparência passiva?", verso: "Publicidade é o preceito constitucional de divulgação do que é público (art. 37 da CF; art. 3º, I, da Lei nº 12.527/2011). Transparência ativa é o mecanismo de ofício: disponibilizar independentemente de solicitações (art. 4º, XI, e art. 29 da Lei nº 14.129/2021). Transparência passiva é o mecanismo por demanda: o pedido individual do requerente (arts. 10 a 16 da Lei nº 12.527/2011).", explicacao: "A publicidade é o dever; a ativa é o mecanismo de ofício; a passiva é o mecanismo por demanda. São complementares: o portal de transparência não dispensa o atendimento de pedidos, e o atendimento de pedidos não supre o dever de divulgar de ofício.", revisao: null, acertos: 0, dificuldade: "medio" },
  { id: "fc-m6-08", modulo: 6, topico: "m6-u1-t3", nivel: "intermediario", frente: "Eficiência e economicidade são sinônimos? E a eficiência prevalece sobre os demais princípios?", verso: "Não são sinônimos, e não há hierarquia absoluta entre os princípios do art. 37. Eficiência é princípio de fim (qualidade do serviço com uso racional de recursos); economicidade é critério de meio (relação custo-benefício na contratação): uma contratação economicamente vantajosa que entregue serviço inacessível ou lento não realiza eficiência. Eficiência orienta o «como fazer», mas não afasta legalidade, impessoalidade, moralidade nem publicidade.", explicacao: "O item que afirma que a eficiência prevalece por ser o princípio mais recente erra em dois pontos: não existe hierarquia e a recentidade do princípio é irrelevante. A eficiência também não autoriza renúncia a direito — os art. 3º, XVI, e 14 da Lei nº 14.129/2021 preservam o atendimento presencial, e o art. 3º, XI, manda eliminar formalidades cujo custo social exceda o risco, barreira digital incluída.", revisao: null, acertos: 0, dificuldade: "medio" },
  { id: "fc-m6-09", modulo: 6, topico: "m6-u1-t3", nivel: "avancado", frente: "Uma regra de decisão de benefício foi cadastrada há dois anos e nunca revisada. Qual é o problema jurídico e qual a providência?", verso: "Dois problemas articulados. Legalidade: a regra aplicada pode não corresponder mais à norma vigente, porque a lei muda e o parâmetro fica. Impessoalidade e moralidade: regras antigas podem espelhar critérios superados ou discriminatórios. Providência: versionamento obrigatório de regras com data de vigência, revisão periódica, responsável nomeado e registro de alterações, além de reprocessamento ou revisão dos casos decididos sob a regra revista.", explicacao: "A versão da regra é evidência de legalidade: sem ela, não se demonstra que o critério aplicado era o vigente na data do fato. O item que trata a ausência de revisão como detalhe de operação está errado — ela é requisito de conformidade do desenho decisório.", revisao: null, acertos: 0, dificuldade: "dificil" },

  // 6.2 Transparência: Lei de Acesso à Informação e Lei de Governo Digital (13 flashcards)
  { id: "fc-m6-10", modulo: 6, topico: "m6-u2-t1", nivel: "basico", frente: "A Lei nº 12.527/2011 se aplica a quais entidades?", verso: "À União, aos Estados, ao Distrito Federal e aos Municípios (art. 1º) e, pelo parágrafo único, aos órgãos públicos da administração direta dos três Poderes e do Ministério Público, inclusive as Cortes de Contas, e às autarquias, fundações públicas, empresas públicas, sociedades de economia mista e demais entidades controladas direta ou indiretamente. O art. 2º estende, no que couber, às entidades privadas sem fins lucrativos que recebam recursos públicos para ações de interesse público, com publicidade restrita à parcela dos recursos recebidos e à sua destinação.", explicacao: "A incidência não decorre do Poder a que o órgão pertença, mas do regime jurídico: uma secretaria estadual autárquica está integralmente submetida ao regime da Lei. O art. 5º, XXXIII, da CF e o art. 37, § 3º, II, e o art. 216, § 2º, da CF são as bases constitucionais do acesso que a Lei regula.", revisao: null, acertos: 0, dificuldade: "facil" },
  { id: "fc-m6-11", modulo: 6, topico: "m6-u2-t1", nivel: "basico", frente: "Quais são as cinco diretrizes do art. 3º da Lei nº 12.527/2011?", verso: "(I) observância da publicidade como preceito geral e do sigilo como exceção; (II) divulgação de informações de interesse público, independentemente de solicitações; (III) utilização de meios de comunicação viabilizados pela tecnologia da informação; (IV) fomento ao desenvolvimento da cultura de transparência na Administração Pública; (V) desenvolvimento do controle social da Administração Pública.", explicacao: "O inciso I é a diretriz que estrutura todo o regime: publicidade como regra e sigilo como exceção, que precisa de fundamento legal (art. 23) e de ato formal de classificação (art. 28). O inciso III é o que legitima o uso de canais digitais e o registro em meio eletrônico.", revisao: null, acertos: 0, dificuldade: "facil" },
  { id: "fc-m6-12", modulo: 6, topico: "m6-u2-t2", nivel: "basico", frente: "Qual é a diferença entre transparência ativa e transparência passiva no ponto de vista do dever e do direito?", verso: "Transparência ativa é dever de ofício: o órgão divulga independentemente de requerimento, em local de fácil acesso, as informações de interesse coletivo ou geral que produz ou custodia (art. 8º da Lei nº 12.527/2011; definição no art. 4º, XI, da Lei nº 14.129/2021). Transparência passiva é direito de pedido: qualquer interessado formula pedido com identificação do requerente e especificação da informação (arts. 10 e 11 da Lei nº 12.527/2011).", explicacao: "O art. 8º, § 2º, torna obrigatória a divulgação em sítios oficiais da internet; o § 3º traz oito requisitos técnicos do sítio. Nenhum dos dois mecanismos sana o descumprimento do outro: a existência de portal não elimina o direito de pedir, e o atendimento de pedidos não supre o dever de divulgar.", revisao: null, acertos: 0, dificuldade: "facil" },
  { id: "fc-m6-13", modulo: 6, topico: "m6-u2-t2", nivel: "intermediario", frente: "Quais são os oito requisitos do sítio oficial previstos no art. 8º, § 3º, da Lei nº 12.527/2011?", verso: "(I) ferramenta de pesquisa de conteúdo que permita acesso objetivo, transparente, claro e em linguagem de fácil compreensão; (II) gravação de relatórios em diversos formatos eletrônicos, inclusive abertos e não proprietários (planilhas e texto); (III) acesso automatizado por sistemas externos em formatos abertos, estruturados e legíveis por máquina; (IV) divulgação em detalhes dos formatos utilizados para estruturar a informação; (V) garantia de autenticidade e integridade das informações; (VI) manutenção atualizada; (VII) indicação de local e instruções para comunicação eletrônica ou telefônica; (VIII) adoção de medidas para garantir a acessibilidade de conteúdo para pessoas com deficiência.", explicacao: "São requisitos de engenharia do portal de transparência, e por isso auditáveis: a ausência de (III) e de (V) é justamente o que impede a abertura de dados nos termos do art. 29 da Lei nº 14.129/2021. O inciso VIII remete ao art. 17 da Lei nº 10.098/2000 e ao art. 9º da Convenção sobre os Direitos das Pessoas com Deficiência.", revisao: null, acertos: 0, dificuldade: "medio" },
  { id: "fc-m6-14", modulo: 6, topico: "m6-u2-t2", nivel: "intermediario", frente: "O que o art. 8º, § 1º, da Lei nº 12.527/2011 define como conteúdo mínimo da divulgação de ofício?", verso: "(I) registro das competências e estrutura organizacional, endereços e telefones das unidades e horários de atendimento; (II) registros de repasses ou transferências de recursos financeiros; (III) registros das despesas; (IV) informações concernentes a procedimentos licitatórios, inclusive editais e resultados, e a todos os contratos celebrados; (V) dados gerais para acompanhamento de programas, ações, projetos e obras, com metas e indicadores; (VI) respostas a perguntas mais frequentes da sociedade.", explicacao: "Publicar parte do rol não cumpre o dever, e o descumprimento é agravado pela desatualização, que impede o controle social (art. 3º, V, da Lei nº 12.527/2011). O inciso V é a base dos indicadores agregados que substituem, com segurança, a publicação nominativa de beneficiários.", revisao: null, acertos: 0, dificuldade: "medio" },
  { id: "fc-m6-15", modulo: 6, topico: "m6-u2-t2", nivel: "intermediario", frente: "Um município com 8.000 habitantes deixou de publicar o relatório de despesas no site, alegando que a transparência ativa lhe é facultativa. O argumento procede?", verso: "Não. O art. 8º, § 4º, da Lei nº 12.527/2011 dispensa os municípios com população até 10.000 habitantes apenas da divulgação obrigatória na internet, e mantém a obrigatoriedade de divulgação, em tempo real, de informações relativas à execução orçamentária e financeira, nos critérios e prazos do art. 73-B da LRF.", explicacao: "A dispensa é pontual, sobre o canal, e não substancial, sobre o dever. O argumento válido seria apenas sobre o meio de publicação; invocar facultatividade para dispensar a própria publicidade é generalização falsa.", revisao: null, acertos: 0, dificuldade: "medio" },
  { id: "fc-m6-16", modulo: 6, topico: "m6-u2-t2", nivel: "intermediario", frente: "O que o órgão pode exigir de quem apresenta pedido de acesso à informação, e o que é vedado exigir?", verso: "Pode exigir apenas a identificação do requerente e a especificação da informação requerida (art. 10, caput, da Lei nº 12.527/2011). É vedado exigir a motivação do pedido (art. 10, § 3º) e vedado que a identificação contenha exigências que inviabilizem o pedido de interesse público (art. 10, § 1º). O pedido pode ser apresentado por qualquer meio legítimo, e o órgão deve viabilizar o encaminhamento pelos sítios oficiais (art. 10, § 2º).", explicacao: "Exigir justificativa do pedido é prática proibida, e a negativa fundada nesse motivo é nula. O que o item de prova cobra é a identificação do que é exigência válida (identificação e especificação) e do que é vedação (motivos e exigências inviabilizantes).", revisao: null, acertos: 0, dificuldade: "medio" },
  { id: "fc-m6-17", modulo: 6, topico: "m6-u2-t2", nivel: "basico", frente: "Quais são os prazos do ciclo de atendimento a pedido de acesso à informação?", verso: "20 dias para resposta (art. 11, § 1º, da Lei nº 12.527/2011), prorrogáveis por mais 10 dias mediante justificativa expressa, da qual o requerente é cientificado (art. 11, § 2º); recurso no prazo de 10 dias a contar da ciência, dirigido à autoridade hierarquicamente superior à que exarou a decisão, que se manifesta no prazo de 5 dias (art. 15); e, contra a negativa do Poder Executivo Federal, recurso à Controladoria-Geral da União (art. 16), com submissão prévia à autoridade hierarquicamente superior.", explicacao: "Prazo é regra vinculante, com hipótese e condição de prorrogação: não se «pondera» o prazo de 20 dias como se fosse princípio. O art. 14 assegura ainda o direito do requerente ao inteiro teor da decisão de negativa, por certidão ou cópia.", revisao: null, acertos: 0, dificuldade: "facil" },
  { id: "fc-m6-18", modulo: 6, topico: "m6-u2-t2", nivel: "intermediario", frente: "O órgão pode cobrar taxa pelo atendimento de pedido de acesso à informação?", verso: "O serviço de busca e de fornecimento de informação é gratuito (art. 12 da Lei nº 12.527/2011, na redação dada pelo art. 52 da Lei nº 14.129/2021). O órgão pode cobrar exclusivamente o valor necessário ao ressarcimento dos custos dos serviços e dos materiais utilizados, e somente quando o atendimento exigir reprodução de documentos; é isento de ressarcimento quem não puder fazê-lo sem prejuízo do sustento próprio ou da família.", explicacao: "Não há finalidade lucrativa na cobrança: o valor cobrado é exclusivamente o necessário ao ressarcimento dos custos utilizados, o que exclui a configuração de taxa. A alternativa que trata a gratuidade como vedação absoluta de qualquer ressarcimento também está errada.", revisao: null, acertos: 0, dificuldade: "medio" },
  { id: "fc-m6-19", modulo: 6, topico: "m6-u2-t3", nivel: "avancado", frente: "O que distingue publicidade administrativa de divulgação irrestrita de dados pessoais?", verso: "PUBLICIDADE ADMINISTRATIVA é a divulgação oficial, pelo próprio órgão, de informações públicas, pelos canais oficiais (sítio, portal de transparência, diário oficial), para informar o cidadão e permitir o controle social: é dever de ofício, e o alvo é o que é público por natureza — competências, despesas, licitações, contratos, programas e indicadores (art. 5º, XXXIII, da CF; art. 3º, I e II, e art. 8º da Lei nº 12.527/2011; art. 29 da Lei nº 14.129/2021). DIVULGAÇÃO IRRESTRITA DE DADOS PESSOAIS é a disponibilização ampla, indiscriminada e sem ponderação de dados que identificam pessoas, sem base legal, finalidade, minimização e proteção — lista de beneficiários com nome, CPF, endereço e diagnóstico, cadastro divulgado em post de rede social: é VEDADA.", explicacao: "O exemplo que resolve a dúvida: publicar nome, cargo e remuneração de servidor no portal é publicidade institucional (art. 29, § 2º, VII, da Lei nº 14.129/2021) — o alvo é a estrutura de pessoal do órgão, não a pessoa do cidadão. O que é vedado é a difusão irrestrita de dados pessoais de cidadãos sem base legal, finalidade e proteção.", revisao: null, acertos: 0, dificuldade: "dificil" },
  { id: "fc-m6-20", modulo: 6, topico: "m6-u2-t3", nivel: "avancado", frente: "Quais são as três condições para que a divulgação de dado pessoal em transparência ativa seja lícita, e quais dispositivos a vedam?", verso: "As três condições: (1) base legal ou consentimento expresso (art. 31, § 1º, II, da Lei nº 12.527/2011) ou hipótese de dispensa do art. 31, § 3º; (2) finalidade de interesse público, com compatibilidade de finalidade e minimização; (3) quando se tratar de abertura de base, anonimização prévia (art. 36 da Lei nº 14.129/2021) ou agregação com vedação de identificação (art. 31, § 3º, II, da Lei nº 12.527/2011). Vedam a divulgação irrestrita: o art. 31 da Lei nº 12.527/2011, o art. 29, § 1º, VIII, da Lei nº 14.129/2021 (privacidade mesmo na transparência ativa) e os arts. 1º e 5º, I e II, da LGPD.", explicacao: "Sem qualquer uma das três condições, não há publicação de dado identificável. A publicidade é preceito geral quanto ao que é público — não quanto ao que é pessoal: invocar o art. 8º da Lei nº 12.527/2011 como fundamento de divulgação nominada ignora os limites do regime.", revisao: null, acertos: 0, dificuldade: "dificil" },
  { id: "fc-m6-21", modulo: 6, topico: "m6-u2-t3", nivel: "avancado", frente: "Quais mecanismos conciliam a transparência pública com a proteção de dados pessoais?", verso: "(1) Anonimização antes da disponibilização, com vedação de identificação (art. 31, § 3º, II, da Lei nº 12.527/2011; art. 36 da Lei nº 14.129/2021); (2) acesso parcial, por certidão, extrato ou cópia, com ocultação da parte sob sigilo (art. 7º, § 2º, da Lei nº 12.527/2011); (3) consentimento expresso da pessoa ou previsão legal para divulgação a terceiros (art. 31, § 1º, II, da Lei nº 12.527/2011); (4) agregação sem identificação, como a contagem de beneficiários por bairro.", explicacao: "Não concilia: publicar a base completa em CSV. E pseudonimização não substitui a anonimização — trocar o nome por um código mantém a associação recuperável por meios adicionais, de modo que o dado continua dado pessoal (art. 5º, I, da LGPD) e a abertura depende de base legal específica.", revisao: null, acertos: 0, dificuldade: "dificil" },
  { id: "fc-m6-22", modulo: 6, topico: "m6-u2-t3", nivel: "avancado", frente: "Responda ao pedido que mistura dados anonimizáveis e dados identificáveis: qual é a conduta correta do órgão?", verso: "Analisar por camada e entregar o máximo possível: produzir versão anonimizada ou agregada e entregá-la; insofar houver retenção, motivar com dispositivo específico, informar o teor integral da decisão de negativa (art. 14 da Lei nº 12.527/2011) e indicar o caminho recursal (art. 11, § 4º); registrar o método e a data da anonimização. A negativa binária e genérica descumpre o dever de fundamentação (art. 11, § 1º, II) e o direito de acesso parcial (art. 7º, § 2º).", explicacao: "Fundamentos que se combinam: publicidade como preceito geral (art. 3º, I), proteção da informação pessoal (art. 31), acesso parcial (art. 7º, § 2º), dever de fundamentar a negativa (art. 11, § 1º, II) e inteiro teor da decisão (art. 14). O item que trata a recusa integral como uniforme está errado.", revisao: null, acertos: 0, dificuldade: "dificil" },

  // 6.3 Proteção de dados pessoais, sigilo, segurança, rastreabilidade e responsabilização (8 flashcards)
  { id: "fc-m6-23", modulo: 6, topico: "m6-u3-t1", nivel: "basico", frente: "A quem se aplica a LGPD e quais são as suas exceções de aplicação?", verso: "O art. 1º dispõe sobre o tratamento de dados pessoais, inclusive nos meios digitais, por pessoa natural ou por pessoa jurídica de direito público ou privado: o Estado é controlador e operador. O art. 3º aplica a lei às operações de tratamento realizadas no território nacional, à oferta de bens e serviços e ao tratamento de indivíduos localizados no país, e aos dados coletados no território. O art. 4º exclui: (I) tratamento por pessoa natural para fins exclusivamente particulares e não econômicos; (II) finalidades exclusivamente jornalísticas ou artísticas (com aplicação dos arts. 7º e 11) ou exclusivamente acadêmicas; (III) finalidades exclusivas de segurança pública, defesa nacional, segurança do Estado, investigação e repressão de infrações penais, com as ressalvas dos §§ 1º e 2º.", explicacao: "As exceções não são isenções totais: a hipótese do inciso II mantém a aplicação de outros dispositivos, e a do inciso III admite uso em desconformidade com a lei ou com o titular. Por isso o órgão público não escapa dos deveres de segurança e de direitos.", revisao: null, acertos: 0, dificuldade: "facil" },
  { id: "fc-m6-24", modulo: 6, topico: "m6-u3-t1", nivel: "intermediario", frente: "Como o art. 5º da LGPD define dado pessoal, dado pessoal sensível, controlador, operador e encarregado?", verso: "Dado pessoal (I): o relativo a pessoa natural identificada ou identificável. Dado pessoal sensível (II): o relativo à origem racial ou étnica, convicção religiosa, opinião política, filiação sindical, dado relativo à saúde ou dado sobre a vida sexual. Controlador (V): quem decide sobre o tratamento. Operador (VI): quem trata por conta do controlador. Encarregado (VII): pessoa física indicada pelo controlador como responsável pelo tratamento. Agentes de tratamento (VIII): controlador, operador e encarregado.", explicacao: "Dado anonimizado (III) é o que, por técnicas que comprometem a identificação razoavelmente, impede a associação a uma pessoa. A pseudonimização não chega lá: mantém a associação por meios adicionais, de modo que o dado continua dado pessoal — e é por isso que só a anonimização autoriza abertura de base (art. 36 da Lei nº 14.129/2021).", revisao: null, acertos: 0, dificuldade: "medio" },
  { id: "fc-m6-25", modulo: 6, topico: "m6-u3-t1", nivel: "basico", frente: "Quais são os direitos do titular do dado pessoal previstos no art. 18 da LGPD?", verso: "Confirmação da existência de tratamento (I); acesso aos dados (II); correção de dados incompletos, inexatos ou desatualizados (III); anonimização, bloqueio ou eliminação de dados desnecessários ou excessivos (IV); portabilidade (V); informação sobre as entidades com as quais compartilhou dados (VI); informação sobre a possibilidade de não fornecer consentimento e suas consequências (VII); revogação do consentimento (VIII).", explicacao: "Direito não listado no art. 18 não pode ser afirmado como previsto ali: o acesso à íntegra de processo administrativo, por exemplo, é direito de acesso a documento administrativo (art. 7º da Lei nº 12.527/2011), e não direito do titular segundo a LGPD. A titularidade vem do art. 17.", revisao: null, acertos: 0, dificuldade: "facil" },
  { id: "fc-m6-26", modulo: 6, topico: "m6-u3-t3", nivel: "intermediario", frente: "O que exige o art. 46 da LGPD, e como ele se conecta ao art. 48 e ao art. 49 da Lei nº 14.129/2021?", verso: "O art. 46 exige que os agentes de tratamento adotem medidas de segurança TÉCNICAS E ADMINISTRATIVAS aptas a proteger os dados pessoais de acessos não autorizados e de situações acidentais ou ilícitas. O art. 48 da Lei nº 14.129/2021 exige sistema de gestão de riscos e de controle interno para a prestação digital de serviços, com controles internos proporcionais aos riscos (causas, fontes, consequências, impactos e relação custo-benefício) e proteção das liberdade civis e dos direitos fundamentais. O art. 49 institui auditoria interna com abordagem baseada em risco e prevenção, detecção e investigação de fraudes.", explicacao: "Quatro características da exigência do art. 46: é dever e não faculdade; é apta, isto é, proporcional ao risco real; é técnica E administrativa — a melhor criptografia não protege contra credencial compartilhada ou processo mal desenhado; e é demonstrável por auditoria. A ausência de registro de auditoria é falha de controle interno (art. 48), sem que isso presuma culpa de servidor.", revisao: null, acertos: 0, dificuldade: "medio" },
  { id: "fc-m6-27", modulo: 6, topico: "m6-u3-t2", nivel: "basico", frente: "Quais são os graus de sigilo e os prazos máximos de restrição de acesso previstos no art. 24 da Lei nº 12.527/2011?", verso: "Ultrassecreta: 25 anos. Secreta: 15 anos. Reservada: 5 anos. Os prazos contam da data de produção (art. 24, § 1º); o § 3º admite termo final pela ocorrência de determinado evento, desde que ocorra antes do transcurso do prazo máximo; e o § 4º é regra de automaticidade — transcorrido o prazo ou consumado o evento, a informação torna-se automaticamente de acesso público. O § 5º impõe observar o interesse público da informação e utilizar o critério menos restritivo possível.", explicacao: "As hipóteses de classificação são as do art. 23, e a fórmula legal é que o risco basta ser possível — não precisa ser atual. O § 2º trata das informações que puderem pôr em risco a segurança do Presidente e Vice-Presidente da República e respectivos cônjuges e filhos, classificáveis como reservadas e sob sigilo até o término do mandato.", revisao: null, acertos: 0, dificuldade: "facil" },
  { id: "fc-m6-28", modulo: 6, topico: "m6-u3-t2", nivel: "intermediario", frente: "Quais são os quatro elementos obrigatórios da decisão de classificação, e quem tem competência para classificar?", verso: "Elementos do art. 28: (I) assunto sobre o qual versa a informação; (II) fundamento da classificação, observados os critérios do art. 23; (III) indicação do prazo de sigilo, contado em anos, meses ou dias, ou do evento que defina o termo final, conforme os limites do art. 24; (IV) identificação da autoridade que classificou. Competência (art. 27): no âmbito federal, o grau de ultrassecreto compete às autoridades de altíssimo escalão; o de secreto, a essas autoridades e aos titulares de autarquias, fundações, empresas públicas e sociedades de economia mista; o de reservado, também às autoridades de direção, comando ou chefia de nível equivalente.", explicacao: "A delegação é permitida, mas a subdelegação é vedada (art. 27, § 1º). O parágrafo único do art. 28 exige que a decisão de classificação seja mantida no mesmo grau da informação classificada. A reavaliação é do art. 29 (de ofício ou por provocação, para desclassificar ou reduzir o prazo) e o art. 30 exige publicação anual dos rol de desclassificados, dos documentos classificados por grau e de relatório estatístico de pedidos.", revisao: null, acertos: 0, dificuldade: "medio" },
  { id: "fc-m6-29", modulo: 6, topico: "m6-u3-t2", nivel: "avancado", frente: "O art. 31 da Lei nº 12.527/2011 cria regime autônomo para a informação pessoal. Quais são os seus limites e exceções?", verso: "O tratamento das informações pessoais deve ser feito de forma transparente e com respeito à intimidade, vida privada, honra e imagem, bem como às liberdades e garantias individuais (caput). O § 1º, I, limita o acesso às informações relativas à intimidade, vida privada, honra e imagem a agentes públicos legalmente autorizados e à própria pessoa, pelo prazo máximo de 100 ANOS a contar da data de produção, INDEPENDENTEMENTE DE CLASSIFICAÇÃO DE SIGILO. O § 1º, II, admite divulgação ou acesso por terceiros diante de previsão legal ou consentimento expresso. O § 2º responsabiliza quem obtiver acesso pelo uso indevido. O § 3º dispensa consentimento nas hipóteses listadas — entre elas a realização de estatísticas e pesquisas científicas de evidente interesse público ou geral, previstas em lei, com vedação de identificação. O § 4º veda invocar a restrição para PREJUDICAR APURAÇÃO DE IRREGULARIDADES em que o titular esteja envolvido.", explicacao: "Consequência que muda o gabarito: dado pessoal não sigiloso continua protegido. Sigilo e proteção de dados pessoais são regimes autônomos e cumuláveis, não alternativas; e o art. 31, § 4º, é salvaguarda de accountability — a proteção da pessoa não pode ser escudo contra a apuração de má-fé do próprio servidor.", revisao: null, acertos: 0, dificuldade: "dificil" },
  { id: "fc-m6-30", modulo: 6, topico: "m6-u3-t3", nivel: "avancado", frente: "Quem responde pelos danos causados por divulgação não autorizada ou uso indevido de informações, e qual é a relação entre a trilha de auditoria e a responsabilização?", verso: "O art. 34 da Lei nº 12.527/2011: os órgãos respondem diretamente pelos danos causados em decorrência da divulgação não autorizada ou da utilização indevida de informações sigilosas ou pessoais, cabendo apuração de responsabilidade funcional nos casos de dolo ou culpa, assegurado o direito de regresso. O art. 32 tipifica as condutas ilícitas do agente público: recusar-se a fornecer, retardar deliberadamente ou fornecer de forma incorreta, incompleta ou imprecisa a informação (I); utilizar indevidamente, subtrair, destruir, inutilizar, desfigurar, alterar ou ocultar informação sob guarda (II); agir com dolo ou culpa na análise das solicitações (III); divulgar ou permitir a divulgação, ou acessar indevidamente, informação sigilosa ou pessoal (IV).", explicacao: "A trilha de auditoria comprova o FATO — quem fez o quê, quando, com que versão da regra —; a imputação exige exame de dolo ou culpa. A ausência de log não prova inexistência da conduta, mas, quando o registro era obrigatório, integra o sistema de controle interno (art. 48 da Lei nº 14.129/2021) e é avaliável como falha organizacional. Tratar o log como prova automática de culpa é erro de leitura.", revisao: null, acertos: 0, dificuldade: "dificil" },

  // 6.4 Uso institucional de redes sociais, conflito de interesse, conduta e netiqueta (7 flashcards)
  { id: "fc-m6-31", modulo: 6, topico: "m6-u4-t1", nivel: "basico", frente: "Qual a diferença jurídica entre o perfil institucional do órgão em rede social e a conta pessoal do servidor?", verso: "O perfil institucional é canal de comunicação do órgão: as publicações nele são comunicações institucionais, sujeitas ao dever de publicidade (art. 8º da Lei nº 12.527/2011), ao regime de dados pessoais e à Lei de Governo Digital, e a titularidade do perfil e do acesso é do órgão. A conta pessoal é uso particular, regido pelo dever de conduta do servidor, pelo dever de reserva e pela vedação de vincular o órgão a posicionamentos pessoais.", explicacao: "O mesmo conteúdo, no canal errado, muda o enquadramento e o responsável. Hashtag, logotipo ou identidade visual não criam vinculação institucional: quem define quem fala pelo órgão é a gestão de acesso ao perfil, e ela deve ser formal, com conta institucional e registro de atividade.", revisao: null, acertos: 0, dificuldade: "facil" },
  { id: "fc-m6-32", modulo: 6, topico: "m6-u4-t1", nivel: "intermediario", frente: "Quais são os controles mínimos de governança de um perfil institucional em rede social?", verso: "Titularidade do perfil no órgão, e não em servidor ou prestador; conta institucional com autenticação multifator; perfis de acesso por função (publicador, editor, aprovador), com desligamento imediato na saída do servidor; política editorial aprovada; registro de cada publicação com data, hora, autor lógico, texto, mídia, versão e aprovador; rotina de correção de erros e escalonamento de matéria sensível; e canal de ouvidoria (art. 21, XI, da Lei nº 14.129/2021).", explicacao: "Sem autoria individual não há responsabilização possível (art. 34 da Lei nº 12.527/2011) e não há como responder ao princípio da publicidade, que exige divulgação de verdade. Senha compartilhada por cinco servidores destrói os dois controles de uma vez — e libera a senha do perfil a todos os servidores é pior: amplia o risco de publicação indevida.", revisao: null, acertos: 0, dificuldade: "medio" },
  { id: "fc-m6-33", modulo: 6, topico: "m6-u4-t1", nivel: "intermediario", frente: "O que deve definir a política editorial de um canal institucional?", verso: "Seis elementos: (1) o que se publica e o que não se publica (campanha institucional, serviço, orientação, divulgação legal, horários, emergência); (2) quem autoriza cada tipo de publicação; (3) o tom da linguagem e a proibição de opinião pessoal; (4) o tratamento de comentários e de reportes (moderação, escalonamento e prazo de resposta); (5) a política de correção de erros e de apoio ao cidadão; (6) a proibição de divulgação de dados pessoais de terceiros e de conteúdo que exponha informações protegidas.", explicacao: "A moderação que pode gerar restrição de participação do cidadão exige critério definido, proporcionalidade e registro, sob o dever de transparência (art. 3º, IV, da Lei nº 14.129/2021) e de accountability (art. 34 da Lei nº 12.527/2011). Publicar informação incorreta e mantê-la é compatível com a condição de obscuridade: a correção integra o dever de publicidade.", revisao: null, acertos: 0, dificuldade: "medio" },
  { id: "fc-m6-34", modulo: 6, topico: "m6-u4-t2", nivel: "intermediario", frente: "O que é conflito de interesse e como se distinguem o conflito real, o potencial e o aparente?", verso: "É a situação em que o interesse pessoal do agente ou servidor público pode influenciar, ou pode razoavelmente parecer influenciar, o exercício de atribuição funcional, comprometendo a imparcialidade ou a impessoalidade. São três elementos: um interesse pessoal (patrimônio, relação, participação societária, vínculo familiar, reputação profissional), uma atribuição ou ato que pode ser influenciado, e uma capacidade real ou aparente de influência. REAL: a influência ocorre. POTENCIAL: a capacidade existe, mas não se exerceu. APARENTE: o observador razoável pode suspeitar de influência, ainda que inexistente.", explicacao: "A distinção não é acadêmica: ela define o tratamento. O conflito real e o potencial demandam, em regra, afastamento ou recusa do ato; o aparente pode ser tratado com transparência, declaração e, conforme o risco, o mesmo afastamento. Item que trata real e potencial como equivalentes está errado.", revisao: null, acertos: 0, dificuldade: "medio" },
  { id: "fc-m6-35", modulo: 6, topico: "m6-u4-t2", nivel: "intermediario", frente: "Qual é o protocolo de tratamento do conflito de interesse no serviço público digital?", verso: "Seis passos: (1) identificação e declaração prévia da situação; (2) formalização e arquivamento da declaração, que não pode ser verbal; (3) afastamento ou recusa do ato específico, com substituição por servidor sem conflito (segregação de funções); (4) transparência — em conflitos de menor impacto, a situação pode ser registrada e comunicada; (5) remessa ao controle e apuração quando houver indício de uso indevido; (6) revisão das decisões tomadas no período de conflito, que podem precisar de reanálise ou de revisão.", explicacao: "O dever de declarar é do servidor; o dever de previr, detectar e corrigir o desenho que permite o conflito é do órgão (art. 48 da Lei nº 14.129/2021), ainda que não haja prova de má-fé individual. A ferramenta mais eficaz é a impessoalidade do processo: quando o ato é regido por critério publicado e auditável, a influência pessoal perde espaço, ainda que ocorra.", revisao: null, acertos: 0, dificuldade: "medio" },
  { id: "fc-m6-36", modulo: 6, topico: "m6-u4-t2", nivel: "intermediario", frente: "Quais condutas são vedadas ao servidor no canal institucional e no canal pessoal?", verso: "No canal institucional é proibido: publicar opinião pessoal, crítica política ou posição individual em nome do órgão; expor dado pessoal de terceiros; usar nome, logotipo ou perfil para interesse pessoal, comercial ou de terceiro; emitir opinião em assunto em curso de apuração, em procedimento administrativo ou em litígio; criar perfis ou campanhas não autorizados; e deixar de escalonar matéria sensível (ameaças, relatos de irregularidade, conteúdo com dados de crianças ou de pessoas em vulnerabilidade, relatos de má-fé). No canal pessoal, o servidor pode expressar opinião, desde que sem vincular o órgão, sem usar informação do cargo e sem expor dado pessoal de terceiro.", explicacao: "O art. 32 da Lei nº 12.527/2011 alcança o servidor como agente público: utilizar indevidamente, subtrair, destruir, alterar ou ocultar informação sob guarda (II) e divulgar ou permitir acesso indevido a informação sigilosa ou pessoal (IV). A ausência de dado pessoal não elimina a proteção do conteúdo nem o dever de reserva; e a Internet livre não afasta esses deveres.", revisao: null, acertos: 0, dificuldade: "medio" },
  { id: "fc-m6-37", modulo: 6, topico: "m6-u4-t3", nivel: "avancado", frente: "Um post institucional publicou foto de cidadão vacinado com nome e número de cartão legíveis. Qual é a sequência correta de providências?", verso: "CONTER: remover o conteúdo ou sanitizar a imagem (recortar os identificadores), avaliando a necessidade de comunicação de erro. PRESERVAR o registro da publicação original (data, hora, autor, texto, mídia). AVALIAR alcance e dano — número de compartilhamentos e cópias existentes. COMUNICAR ao cidadão, quando o risco de dano for relevante, com orientação sobre a exposição do número do cartão. APURAR a publicação: quem autorizou, se houve verificação prévia, se a política editorial foi seguida. CORRIGIR O PROCESSO: verificação obrigatória de dados pessoais antes de publicar, com aprovação registrada por função.", explicacao: "Fundamento: art. 31, § 1º, II, da Lei nº 12.527/2011 (divulgação de informação pessoal por terceiros somente com previsão legal ou consentimento expresso) e art. 5º, I, da LGPD. O aceite da foto para arquivo de campanha não equivale a consentimento para difusão em rede social com dado correlato: trocar a finalidade é desvio de finalidade.", revisao: null, acertos: 0, dificuldade: "dificil" },

  // 6.5 Acessibilidade e inclusão digital (5 flashcards)
  { id: "fc-m6-38", modulo: 6, topico: "m6-u5-t1", nivel: "basico", frente: "Qual a diferença entre acessibilidade e inclusão digital?", verso: "Acessibilidade é a propriedade do artefato digital (página, documento, vídeo, formulário) de ser perceptível, operável, compreensível e robusto para pessoas com deficiência ou com outras limitações de interação. Inclusão digital é o resultado social de permitir que toda a população, com diferentes níveis de conexão, habilidade, alfabetização digital e equipamento, alcance o serviço.", explicacao: "Um portal acessível que exige navegador de última geração e conexão rápida não é inclusivo; um serviço presencial não é acessível — mas é includente para quem não usa o digital. Efeito no gabarito: o item que confunde as duas está errado, e o serviço público inacessível é um serviço negado a uma parte da população.", revisao: null, acertos: 0, dificuldade: "facil" },
  { id: "fc-m6-39", modulo: 6, topico: "m6-u5-t1", nivel: "intermediario", frente: "Quais são as quatro dimensões da acessibilidade de conteúdo digital, e o que se exige em cada uma?", verso: "PERCEPTÍVEL: texto alternativo em imagens que transmitem informação, legenda em vídeo com áudio, transcrição de áudio, contraste suficiente entre texto e fundo e informação não transmitida apenas por cor. OPERÁVEL: navegação completa por teclado, com foco visível e ordem lógica, tempo suficiente para completar a tarefa, ausência de conteúdo que pisca acima do limiar de risco e alvos de toque com tamanho adequado. COMPREENSÍVEL: rótulos de campo explícitos, instruções antes da tarefa e mensagens de erro indicativas. ROBUSTO: associação programática entre o rótulo visível e o controle, para que a tecnologia assistiva identifique o campo.", explicacao: "Rótulo gerado apenas por placeholder, que desaparece ao digitar, quebra a associação e exclui quem usa leitor de tela; um formulário em fonte de 8 pontos prejudica operabilidade e legibilidade. O item que situa o texto alternativo na dimensão operável está errado: ele é medida da dimensão perceptível.", revisao: null, acertos: 0, dificuldade: "medio" },
  { id: "fc-m6-40", modulo: 6, topico: "m6-u5-t2", nivel: "basico", frente: "Por que a digitalização de um serviço público não pode extinguir o atendimento presencial?", verso: "Porque o art. 3º, XVI, da Lei nº 14.129/2021 assegura a permanência da possibilidade de atendimento presencial, conforme as características, a relevância e o público-alvo do serviço, e o art. 14 exige que a prestação digital ocorra por tecnologias de amplo acesso, inclusive de baixa renda e de áreas rurais e isoladas, sem prejuízo do atendimento presencial.", explicacao: "A conservação do atendimento presencial não é resíduo do modelo antigo: é a garantia de que a digitalização não se converta em exclusão. O art. 3º, III, assegura a via digital e não revoga a via presencial — apagar a ressalva do inciso XVI é a armadinha mais comum sobre a Lei de Governo Digital.", revisao: null, acertos: 0, dificuldade: "facil" },
  { id: "fc-m6-41", modulo: 6, topico: "m6-u5-t3", nivel: "intermediario", frente: "Formato aberto garante acessibilidade? E qual é a função do dicionário de dados na publicação de dados abertos?", verso: "Não. Formato aberto é condição de reutilização e de transparência (art. 4º, IV e VI, da Lei nº 14.129/2021); acessibilidade é condição de percepção e operação. O dicionário de dados descreve cada campo, sua unidade, seu significado e sua origem, atendendo ao art. 29, § 1º, III, da Lei nº 14.129/2021 (descrição suficiente da estrutura e da semântica dos dados) e ao art. 8º, § 3º, IV, da Lei nº 12.527/2011 (divulgação dos formatos utilizados para estruturar a informação).", explicacao: "Sem dicionário, o dado é publicado e permanece inutilizável pelo cidadão comum; e um PDF de páginas escaneadas não é legível por máquina nem pesquisável — deve vir de base estruturada, com CSV e dicionário, e oferecer versão acessível em documento com títulos e tabelas marcadas. O CSV não é acessível por si só.", revisao: null, acertos: 0, dificuldade: "medio" },
  { id: "fc-m6-42", modulo: 6, topico: "m6-u5-t3", nivel: "intermediario", frente: "Como se estrutura a verificação de conformidade de um portal em acessibilidade, e qual evidência ela produz?", verso: "Cinco etapas: (1) definir os critérios adotados e os artefatos no escopo; (2) verificação automática, com registro de data, ferramenta e resultado; (3) revisão manual do conteúdo, da linguagem e da estrutura; (4) teste com usuários, com registro de perfil, tarefa e barreira observada (art. 24, VIII, da Lei nº 14.129/2021); (5) plano de correção com responsável, prazo e reavaliação, com publicação do resultado e indicação dos canais alternativos de atendimento.", explicacao: "O teste automatizado detecta parte das barreiras (rótulos ausentes, contraste insuficiente, ordem de tabulação), mas não avalia a clareza da linguagem, a coerência do fluxo, a usabilidade com tecnologia assistiva nem a compreensão de quem usa a interface. O relatório deve ser auditável por terceiro (art. 49 da Lei nº 14.129/2021).", revisao: null, acertos: 0, dificuldade: "medio" },

  // 6.6 Automação de decisões, supervisão humana, estudos de caso e resolução de questões (7 flashcards)
  { id: "fc-m6-43", modulo: 6, topico: "m6-u6-t1", nivel: "intermediario", frente: "Quais são os níveis de automação de decisão administrativa usados como ferramenta de governança?", verso: "N0 — decisão manual pura, com apoio de consulta documental. N1 — apoio à decisão: o sistema calcula, classifica ou produz escore, e o servidor decide. N2 — decisão automatizada com revisão prévia: só produz efeito após revisão humana. N3 — decisão automatizada com revisão posterior ou amostral: o efeito é imediato. N4 — decisão automatizada com autorização prévia em alçada: o sistema decide dentro de limites e escalona o que sai da faixa. N5 — automação plena: o sistema decide e o ato se forma sem intervenção.", explicacao: "A classificação não é legal: é ferramenta de governança. Regra extraída dela: quanto maior o nível, maior o conjunto de salvaguardas, com proporcionalidade direta ao direito afetado (art. 48, II, da Lei nº 14.129/2021). Exemplo que separa níveis: sistema que nega automaticamente e só aciona o servidor se o cidadão reclamar é N3 com revisão reativa; sistema que nega e escala ao supervisor quando o valor ultrapassa o limite é N4, com alçada publicada.", revisao: null, acertos: 0, dificuldade: "medio" },
  { id: "fc-m6-44", modulo: 6, topico: "m6-u6-t1", nivel: "basico", frente: "Quais são os requisitos de conformidade comuns a todo ato decisório automatizado?", verso: "Sete: (1) base normativa da competência e do critério; (2) critério escrito e versionado, com data de vigência; (3) registro da decisão — identificador do caso, parâmetros usados, versão da regra ou do modelo, data e hora e autor lógico do ato; (4) motivação comunicável, com o fundamento e o critério efetivamente aplicado, em linguagem clara (art. 3º, VII, da Lei nº 14.129/2021); (5) rastreabilidade e não repúdio (art. 43, I e IV, da Lei nº 14.129/2021; art. 34 da Lei nº 12.527/2011); (6) segurança e proteção de dados (art. 46 da LGPD); (7) canal de contestação.", explicacao: "A reversibilidade da decisão não afasta o dever de registrar: o registro é o que permite apurar dolo ou culpa e sustentar o art. 34 da Lei nº 12.527/2011. E a motivação não é dispensada em decisão de risco baixo — ela é conteúdo do ato, não formalidade da forma eletrônica.", revisao: null, acertos: 0, dificuldade: "facil" },
  { id: "fc-m6-45", modulo: 6, topico: "m6-u6-t1", nivel: "intermediario", frente: "A automação transfere ao fornecedor do sistema a responsabilidade pelo ato administrativo praticado?", verso: "Não. O nível de automação não transfere responsabilidade: o órgão responde pelos danos decorrentes de divulgação não autorizada ou uso indevido de informações (art. 34 da Lei nº 12.527/2011) e responde pelo ato administrativo que o sistema produziu em seu nome. O contrato com o fornecedor é relação de direito privado, não transferência de poder público.", explicacao: "A assinatura eletrônica define a autoria do ato (art. 7º da Lei nº 14.129/2021), mas o dever de resposta do órgão permanece. O que o contrato faz é disciplinar o dever de logs de inferência e de auditoria — não deslocar o dever público. É por isso que o desenho do controle de acesso continua sendo responsabilidade do órgão.", revisao: null, acertos: 0, dificuldade: "medio" },
  { id: "fc-m6-46", modulo: 6, topico: "m6-u6-t1", nivel: "avancado", frente: "Quais são os seis elementos de desenho da supervisão humana sobre decisões automatizadas?", verso: "(1) Papel e autoridade — quem revisa, com que competência e com acesso à informação necessária (supervisor sem acesso aos dados não pode revisar; sem autoridade para rever, apenas sugere); (2) alçada de revisão — por impacto, por gatilho e por amostragem aleatória; (3) critério de escalonamento objetivo e publicado — o que dispara a escalada, para quem ela vai, em que prazo e com que prioridade; (4) registro da revisão — revisor, caso, o que a decisão automatizada decidiu, o que mudou, o fundamento e a data; (5) indicadores — taxa de reversão, concordância entre decisão automatizada e decisão revisada, tempo médio de revisão, volume por alçada e distribuição de reversões por subgrupo; (6) retroalimentação ao desenho.", explicacao: "Supervisão sem alçada, sem registro e sem indicadores é teatro de governança: em auditoria com abordagem baseada em risco (art. 49 da Lei nº 14.129/2021) é lido como controle inexistente. A reversão concentrada em um público é sinal de viés de dados, não apenas de erro pontual.", revisao: null, acertos: 0, dificuldade: "dificil" },
  { id: "fc-m6-47", modulo: 6, topico: "m6-u6-t1", nivel: "avancado", frente: "Por que a revisão de decisões automatizadas apenas quando o cidadão reclama é um desenho insuficiente?", verso: "Porque a revisão por reclamação depende de informação, acesso e capacidade de ação do titular: o erro de sistema aparece justamente onde há mais capacidade de reclamar e desaparece onde há menos. Some-se a isso o limite da amostragem aleatória simples, que pode não atingir o subgrupo onde o erro se concentra. O desenho correto combina amostra aleatória estratificada (por território e por faixa do benefício, por exemplo) com gatilhos objetivos de risco e revisão integral dos casos de maior impacto.", explicacao: "Modelos de revisão: prévia (o ato só existe após aprovação — máxima segurança, menor eficiência), posterior integral, posterior amostral e por reclamação; os dois últimos só se justificam com gatilho de risco implementado. A revisão por reclamação é gatilho complementar, não método de aferição de desempenho.", revisao: null, acertos: 0, dificuldade: "dificil" },
  { id: "fc-m6-48", modulo: 6, topico: "m6-u6-t2", nivel: "avancado", frente: "No caso de uso de ferramenta de IA generativa para redigir resposta oficial a um cidadão, qual é o problema central e qual é a providência correta?", verso: "O núcleo do problema é a ausência de revisão e de verificação, não a ferramenta: publicar saída não verificada como comunicação oficial viola o dever de veracidade (art. 5º da Lei nº 12.527/2011) e de linguagem clara (art. 3º, VII, da Lei nº 14.129/2021), e usar o texto do cidadão como contexto é tratamento de dado pessoal sem base legal avaliada (art. 5º, I, e art. 4º, da LGPD). Providência: corrigir e comunicar ao cidadão o erro; preservar o registro da publicação original; apurar o uso de dado de terceiro; e instituir política de uso de IA com revisão humana obrigatória, lista de usos proibidos (dado pessoal, dado sensível, informação sigilosa, credencial) e registro de modelo, prompt, data e revisor.", explicacao: "Enquadrar o caso como «uso de IA é proibido» seria erro de leitura, tão grave quanto publicar sem conferência: o apoio de redação com revisão humana é legítimo; o que não é legítimo é publicar saída não verificada como comunicação oficial. O produto publicado é de responsabilidade do órgão.", revisao: null, acertos: 0, dificuldade: "dificil" },
  { id: "fc-m6-49", modulo: 6, topico: "m6-u6-t3", nivel: "avancado", frente: "Quais são as providências imediatas diante de incidente com exposição de dados pessoais?", verso: "Oito passos: (1) conter — revogar credenciais, isolar o vetor e interromper o fluxo; (2) preservar a evidência ANTES de qualquer rotação de credencial, limpeza de log ou alteração de configuração; (3) avaliar a extensão real — quais registros, quais campos, por quanto tempo, houve uso posterior; (4) comunicar internamente ao encarregado, à autoridade competente e à gestão, com registro da decisão; (5) avaliar e documentar a comunicação ao titular conforme o risco ao titular (identificação, fraude, discriminação, estigmatização); (6) analisar o desenho do controle que falhou (art. 46 da LGPD; art. 48 da Lei nº 14.129/2021); (7) corrigir e verificar (art. 49 da Lei nº 14.129/2021); (8) registrar o incidente e as decisões no sistema de riscos.", explicacao: "Destruir registros de acesso para reduzir a exposição destrói prova e agrava a apuração (art. 32, II, da Lei nº 12.527/2011). E decidir a comunicação ao titular «para evitar pânico», com base subjetiva, contraria o dever de proteção: o critério é a avaliação documentada de risco ao titular.", revisao: null, acertos: 0, dificuldade: "dificil" },
  { id: "fc-m6-50", modulo: 6, topico: "m6-u6-t3", nivel: "intermediario", frente: "Quais são os sete passos do método de resolução de item de prova sobre ética e responsabilidade digital?", verso: "(1) Ler o enunciado até o fim e identificar o sujeito (quem age) e a conduta (o que foi feito); (2) identificar o regime aplicável — acesso à informação, proteção de dados, sigilo, uso de canal, conduta ou automatização; (3) identificar o princípio em jogo entre os cinco do art. 37 da CF; (4) localizar o dispositivo e citar número e parágrafo; (5) verificar o que o item afirma, procurando termo absoluto, generalização e mistura de regimes; (6) testar a alternativa contra o dispositivo; (7) descartar as alternativas que apenas parecem corretas, por trocar termo do regime ou ampliar o alcance da norma.", explicacao: "Quatro armadilhas de leitura: o enunciado truncado, que omite o contexto que salva a conduta; a conduta que não é o illicitio, em que o item cobra o regime aplicável; o regime misto, em que há duas condutas e cada uma tem regime próprio; e o item com prazo, que exige o número exato. Começar pela alternativa que parece mais completa inverte o viés de leitura e produz justamente o erro que o item quer testar: a identidade do regime, o número do dispositivo ou o alcance da norma.", revisao: null, acertos: 0, dificuldade: "medio" }
];
